import json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def write_course(code,title,short,overview,journey,groups,rows,essentials,challenge,extra_sources=[]):
 topics=[]
 for line in rows.strip().splitlines():
  group,name,terms,pages,core,explanation,example,confusion,prompt,answer=line.split('|')
  slug=code.lower()+'-'+re.sub(r'[^a-z0-9]+','-',name.lower()).strip('-')
  refs=[{'id':code,'pages':[int(x) for x in pages.split(',')]}]
  if name=='Commodity fetishism':refs.append({'id':'marx-capital-fetishism'})
  if name in ['Differance and aporia','Logocentrism']:refs.append({'id':'derrida-differance'})
  if name in ['Pidgins and pidginization','Creoles and creolization']:refs.append({'id':'e404-creole-genesis'})
  if name in ['Code-switching','Code-mixing and the matrix language']:refs.append({'id':'e404-codeswitch'})
  if name in ['Gender and language practices','Gendered interaction','Sexism and language reform']:refs.append({'id':'e404-gender-local'})
  if name in ['Fossilization','Stabilization and fossilization']:refs.append({'id':'e404-fossilization'})
  qs=[{'id':slug+'-core','prompt':'Explain '+name.lower()+' briefly.','type':'definition','difficulty':'foundation','essential':name in essentials,'shortAnswer':core,'answer':core+' '+explanation,'keyPoints':[core,explanation],'followUps':[slug+'-apply']},{'id':slug+'-apply','prompt':prompt,'type':'criticism' if name in challenge else 'application','difficulty':'challenge' if name in challenge else 'applied','essential':False,'shortAnswer':answer.split('. ')[0]+('.' if '. ' in answer else ''),'answer':answer,'keyPoints':[answer],'followUps':[]}]
  topics.append({'id':slug,'groupId':code.lower()+'-'+group,'title':name,'aliases':[],'core':core,'explanation':explanation,'example':'Teaching illustration: '+example,'confusion':confusion,'syllabusTerms':terms.split(';'),'sources':refs,'related':[],'questions':qs})
 if code=='E403':
  broad=[('form',3,'What is Formalism?','Formalism studies the devices and organisation that create literary effects.','It foregrounds how a work uses language and form, including literariness and defamiliarization.'),('structural',7,'What is structuralism?','Structuralism examines how elements acquire meaning through relations within a system.','In literary study, it investigates sign systems, narrative conventions and contrasts rather than treating each element as self-contained.'),('reader',12,'What is reader-response criticism?','Reader-response criticism examines the reader’s role in the production of literary meaning.','Different approaches emphasise experience, textual gaps, historical expectations or interpretive conventions.'),('marx',16,'What is Marxist literary criticism?','Marxist criticism examines literature in relation to material conditions, class and ideology.','It asks how texts and their production reproduce, negotiate or challenge social relations and economic power.'),('feminist',21,'What is feminist literary criticism?','Feminist criticism examines gendered representation, literary production and relations of patriarchal power.','It can analyse stereotypes, recover women’s writing and investigate intersections with race, class and colonial histories.'),('psycho',26,'What is psychoanalytic criticism?','Psychoanalytic criticism uses theories of unconscious desire, conflict and identification to interpret texts.','It may examine characters, narrative patterns or reading processes, while recognising that interpretation does not establish a clinical diagnosis.'),('poststructural',31,'What does deconstruction examine?','Deconstruction examines tensions and dependencies that unsettle a text’s apparent conceptual stability.','It attends to hierarchies, exclusions and aporias through close textual engagement; it is not arbitrary destruction of meaning.'),('postmodern',36,'What is postmodernism in cultural theory?','Postmodernism names diverse cultural and intellectual tendencies questioning totalising narratives, originality and stable meanings.','Its features and political implications are contested; examples include stylistic recycling, intertextuality and scepticism toward universal legitimation.'),('postcolonial',39,'What does postcolonial criticism study?','Postcolonial criticism investigates colonial power and its continuing effects on representation, culture and identity.','It also examines agency, resistance and the inequalities that can survive formal independence.'),('culture',43,'What does cultural theory study?','Cultural theory investigates how practices, institutions and representations produce meaning and social identities.','It studies everyday and prestigious forms, connecting culture with power, consumption and contested interpretation.')]
  for group,page,prompt,shortans,detail in broad:
   t=next(t for t in topics if t['groupId']=='e403-'+group)
   t['questions'].append({'id':'e403-'+group+'-approach','prompt':prompt,'type':'definition','difficulty':'foundation','essential':False,'shortAnswer':shortans,'answer':shortans+' '+detail,'keyPoints':[shortans,detail],'sources':[{'id':'E403','pages':[page]}],'followUps':[t['questions'][0]['id']]})
 c={'id':code,'title':title,'shortTitle':short,'overview':overview,'journey':journey,'sources':[{'id':code,'title':code+'.pdf','kind':'pdf','file':code+'.pdf','pageCount':84 if code=='E403' else 51}]+extra_sources,'groups':[{'id':code.lower()+'-'+g,'title':t,'syllabus':ss} for g,t,ss in groups],'topics':topics}
 path=ROOT/'content'/f'{code}.json';path.write_text(json.dumps(c,indent=2,ensure_ascii=False),encoding='utf-8')
 assert sum(q['essential'] for t in topics for q in t['questions'])==20
 assert all(any(s in t['syllabusTerms'] for t in topics) for _,_,ss in groups for s in ss)
 print(code,len(topics),'topics',sum(len(t['questions']) for t in topics),'questions')
 return c

g403=[('form','Formalism and New Criticism',['Defamiliarization (Shklovsky)','Foregrounding (Mayakovsky)','Practical criticism (Richards)']),('structural','Structuralism and Semiotics',['Sign and signification','Paradigm and syntagm','Binary oppositions','Mythoi','Archetypal criticism (Frye)','Narratology (Todorov)','Mythology (Barthes)']),('reader','Reader-Oriented Theories',['Hermeneutics','Phenomenology','Horizon of expectations (Jauss)','Reception theory (Iser)','Speech act theory']),('marx','Marxist Literary Theory',['Dialectical materialism','Base and superstructure','Ideology','Alienation','Commodity fetishism','Hegemony (Gramsci)','ISA (Althusser)']),('feminist','Feminist Literary Theory',['Androgyny (Woolf)','Other (Beauvoir)','Images of Women criticism (Millett)','Gynocriticism (Showalter)','Ecriture feminine (Cixous)','Black feminist criticism (Smith)','Postcolonial feminism (Spivak)']),('psycho','Psychoanalytic Criticism',['Oedipus complex','The unconscious','Drives and defenses','Dream-work','Object relations theory','Imaginary, Symbolic and Real','Trauma']),('poststructural','Post-structuralism and Deconstruction',['Logocentrism','Differance and aporia (Derrida)','Jouissance (Kristeva)','Death of the author (Barthes)','Rhizome','Deterritorialization','Becoming','Disciplinary discourse (Foucault)']),('postmodern','Postmodernism',['Capitalism (Eagleton)','Grand narrative (Lyotard)','Intertextuality (Kristeva)','Hyperreality (Baudrillard)','Pastiche (Jameson)']),('postcolonial','Postcolonialism',['Othering','Diaspora','Hybridity','Double consciousness','Subaltern','Mimicry','Neocolonialism']),('culture','Cultural Theory',['Culture','Popular culture','Consumption','Representation (Hall)'])]
r403='''
form|Defamiliarization|Defamiliarization (Shklovsky)|3,49|Defamiliarization makes familiar things seem unfamiliar, renewing perception.|Shklovsky associates art with slowing habitual perception through unusual perspective, description or form.|Describe a lift as a small room that carries people through a building; the unfamiliar wording renews attention.|It concerns an effect on perception, not simply using difficult vocabulary.|How could a familiar bus journey be defamiliarized?|Describe it through someone encountering buses for the first time, attending to its sounds and rituals. The unusual perspective interrupts habitual recognition.
form|Foregrounding|Foregrounding (Mayakovsky)|4,49,50|Foregrounding makes features of language especially noticeable.|Deviation or patterned repetition can draw attention to sound, syntax or wording. Mayakovsky illustrates startling poetic language; the concept is associated with Prague School work.|Repeated initial sounds in a slogan make its wording prominent.|Foregrounding can occur outside poetry and need not depend only on deviation.|Does repeated alliteration count as foregrounding even without unusual grammar?|Yes. Repetition can make a sound pattern salient. Foregrounding includes parallelism as well as departures from expected language.
form|Practical criticism|Practical criticism (Richards)|4,5|Practical criticism closely analyses a text with external identifying information withheld.|Richards used anonymous poems to investigate readers' responses and misunderstandings. Attention falls on words, tone, imagery and their relations.|Read a poem without knowing its author, then justify a reading from its wording.|A reading exercise without biography does not establish that historical context never matters.|Why did Richards withhold authors' names in his reading experiments?|It reduced reliance on reputation and background knowledge, making readers' textual judgments and interpretive difficulties more visible.
form|New Criticism and close reading|Practical criticism (Richards)|5,6|New Criticism studies the internal relations of literary language through close reading.|It often seeks organic unity through tensions, paradoxes and irony. Form and meaning are understood as closely interdependent.|Explain how a poem's opposing images contribute to an overall interpretation.|Close reading is a method used by many approaches, not the exclusive property of New Criticism.|What would a New Critic examine before discussing a poet's biography?|The work's diction, imagery, rhythm, ambiguities, irony and structure, explaining how these features interact within the text.
structural|Sign and signification|Sign and signification|7,8|A Saussurean sign links a signifier with a signified; signification is meaning production.|The signifier is the form and the signified is the concept. Their association is conventional within a language system.|The sound pattern of tree calls up a concept; another language uses a different form.|The signified is a concept, not the physical object itself.|Why does another language's different word for tree support arbitrariness?|It shows that the sound–concept association is socially conventional rather than a necessary natural resemblance.
structural|Paradigm and syntagm|Paradigm and syntagm|8|A paradigm concerns alternatives; a syntagm concerns combinations.|A speaker selects among possible items and combines selected items into an organised sequence.|In the dog sleeps, cat can replace dog paradigmatically; the whole sequence is syntagmatic.|Selection and combination are related axes, not two separate kinds of language.|Identify both axes in the phrase a bright student.|Bright could be replaced by quiet or talented on the selection axis. The ordered combination of determiner, adjective and noun is the syntagmatic axis.
structural|Binary oppositions|Binary oppositions|8,9|Binary oppositions organise meaning through paired contrasts.|Structuralist analysis examines how contrasts such as nature/culture organise a text. Later critics ask whether one term is privileged and how the opposition is unsettled.|A story opposes city and village, associating each with different values.|A contrast need not be a simple or universal natural division.|How could a character undermine a city/village binary?|A character may combine traits assigned to both sides, revealing that the text's supposedly separate categories depend on exclusions and overlaps.
structural|Mythoi and archetypal criticism|Mythoi;Archetypal criticism (Frye)|9|Frye's mythoi are recurring narrative patterns used in archetypal criticism.|His seasonal scheme associates comedy with spring, romance with summer, tragedy with autumn, and irony/satire with winter.|A story of social renewal ending in celebration fits a comic pattern.|A critical classification is an interpretive framework, not proof that every culture tells identical stories.|Which Fryean mythos would a heroic quest ending in victory most readily suggest?|Romance, associated with summer and idealised adventure. The fit should be justified from the narrative rather than assumed from one isolated feature.
structural|Narratology and narrative order|Narratology (Todorov)|9,10|Narratology studies how narratives are structured and presented.|Distinguish the chronological sequence of events from their artistic arrangement. Todorov's model describes equilibrium, disruption and a changed equilibrium.|A novel starts with a death, then returns to the events that led to it.|Narrative sequence is not necessarily chronological event order.|How does a flashback distinguish story from plot?|The event belongs earlier in chronological story time but is presented later in the plot, shaping suspense and interpretation.
structural|Barthes's myth|Mythology (Barthes)|10,11|For Barthes, myth makes historically constructed cultural values appear natural.|A first-level sign can become the signifier of a second-level ideological message. Analyse what a representation encourages audiences to take for granted.|An advert links a product with an idealised national lifestyle.|Myth here is not limited to ancient stories or simply a factual lie.|How can an advertisement turn an ordinary meal into a national myth?|It can attach ideas of authentic national identity to selected foods, presenting a cultural association as an obvious natural essence.
reader|Hermeneutics|Hermeneutics|12,13|Hermeneutics concerns interpretation and understanding.|Interpretation moves between parts and whole and is shaped by historical assumptions. Different hermeneutic traditions place different weight on author, history and reader.|An ending changes your understanding of an earlier scene, prompting rereading.|The hermeneutic circle is a productive movement of understanding, not merely circular proof.|How does rereading illustrate the hermeneutic circle?|A developing sense of the whole changes how individual passages are understood, while those passages revise the interpretation of the whole.
reader|Phenomenology|Phenomenology|13|Phenomenology investigates how things appear in experience and consciousness.|In literary study it can focus on the structures of reading experience. Husserl's intentionality means consciousness is directed toward something.|Describe how a narrative progressively alters a reader's perception of its narrator.|Intentionality in phenomenology is not simply an author's intended message.|What would a phenomenological reading notice about suspense?|It would examine how the text shapes the reader's anticipation, attention and experience over time, rather than only identifying the final plot outcome.
reader|Horizon of expectations|Horizon of expectations (Jauss)|13,14|A horizon of expectations is the historically shaped background readers bring to a work.|Genre knowledge, earlier reading and cultural assumptions affect reception. A new work may confirm or challenge these expectations.|Readers expecting a conventional detective ending encounter an unresolved mystery.|Jauss stresses historical reception; individual preference alone is too narrow.|Why can a once-shocking novel seem conventional to later readers?|Literary conventions and cultural expectations change. Later readers may already know the innovations that disrupted the work's first audience.
reader|Reception theory and gaps|Reception theory (Iser)|14,15|Iser treats reading as an interaction in which readers realise a text's possibilities.|Texts guide inference while leaving gaps. The implied reader is a role structured by the text, distinct from any actual individual.|Readers infer a character's motive from incomplete dialogue and action.|Gaps permit interpretation but do not make every reading equally well supported.|Can Iser's gaps justify any interpretation a reader invents?|No. Interpretive activity is guided and constrained by textual structures and evidence, even though it is not exhaustively predetermined.
reader|Speech acts|Speech act theory|15|Speech acts are actions performed through utterances.|Distinguish locution, illocution and perlocution: what is said, the act performed, and its effect. Appropriate conditions matter to the act's success.|I promise to return performs a commitment rather than merely describing one.|An intended effect is not guaranteed to occur.|How can a character's promise be analysed at three speech-act levels?|Identify the words and content, the act of promising, and its actual effect, such as reassuring or disappointing another character.
marx|Dialectical materialism|Dialectical materialism|16|Dialectical materialism examines change through contradictions in material conditions.|In Marxist analysis, economic organisation and conflict help explain social transformation. Avoid treating thesis–antithesis–synthesis as a mechanical formula for every event.|Conflicting interests of workers and owners generate tensions within production.|Materialism here concerns explanatory priority, not a personal love of possessions.|Why would a Marxist critic connect a family conflict with property relations?|Property and economic dependence can organise the characters' choices and conflicts. The critic examines those material conditions rather than treating the conflict as purely private.
marx|Base and superstructure|Base and superstructure|17|The base concerns economic production relations; superstructure concerns institutions and cultural forms.|The relation is complex rather than a one-way copying process. Art and institutions can have relative autonomy while remaining socially situated.|A novel's publication depends on markets, yet its form can challenge dominant values.|Economic influence does not mean every artistic detail is mechanically caused by economics.|Does the base–superstructure model require art to mirror the economy directly?|A rigid version would, but more nuanced Marxist approaches allow mediation, contradiction and relative autonomy in culture.
marx|Ideology|Ideology|17,18|Ideology comprises socially situated beliefs and representations that organise understanding.|Marxist criticism often examines how dominant values appear natural and how texts reproduce or challenge them.|A story repeatedly presents inherited privilege as deserved personal superiority.|Ideology can operate through ordinary assumptions, not only explicit propaganda.|How can a children's story convey ideology without discussing politics?|Its patterns of reward, authority and normality can teach assumptions about gender, class or success through apparently ordinary narrative choices.
marx|Alienation|Alienation|18|Alienation describes estrangement from one's labour, its products, other people or human capacities.|In Marx's account, capitalist labour can confront workers as an externally controlled activity whose products belong to others.|A worker makes one component repeatedly without control over the finished product or working process.|Alienation is more specific than simply feeling lonely or bored.|Why might a worker feel alienated even while working among many colleagues?|Social proximity does not remove lack of control over labour, separation from its product or competitive relations within production.
marx|Commodity fetishism|Commodity fetishism|18,19|Commodity fetishism makes social relations among producers appear as relations among things.|Marx examines how commodity exchange obscures the social labour relations through which value is organised.|A commodity's price appears to be its self-contained property while the labour relations behind production disappear from view.|It is not simply loving brands, nor does use-value literally cease to exist.|Why is calling someone a shopaholic an incomplete explanation of commodity fetishism?|The concept concerns the social form of commodity relations and value, not merely an individual's excessive desire to buy goods.
marx|Hegemony|Hegemony (Gramsci)|19|Hegemony is leadership and dominance maintained through consent as well as power.|Gramsci highlights how institutions and common sense secure acceptance of a social order. Consent can coexist with coercion and resistance.|An unequal hierarchy is accepted as natural merit through repeated cultural messages.|Hegemony does not imply that force disappears or consent is unanimous.|How can popular entertainment contribute to hegemony?|It can normalise dominant values through attractive stories and everyday assumptions, while audiences and alternative texts may contest those meanings.
marx|Ideological state apparatuses|ISA (Althusser)|19,20|Althusser's ISAs reproduce social relations primarily through ideology.|Education, family, religion and media help constitute subjects within social norms. Interpellation names the process of recognising oneself in an ideological address.|A school routine positions pupils as obedient, assessed subjects.|ISAs and repressive institutions differ by predominant operation; neither is exclusively ideology or force.|Why might a school be analysed as an ideological state apparatus?|Its routines, curriculum and classifications can reproduce norms and subject positions that support existing social relations, beyond transmitting neutral information.
feminist|Androgyny|Androgyny (Woolf)|21|Woolf's androgynous mind is a creative ideal drawing beyond rigid gender divisions.|She connects creative possibility with material independence and freedom from restrictive gender-consciousness.|A writer creates characters without confining imagination to prescribed masculine or feminine traits.|This is a literary concept, not a clinical or biological classification.|How does Woolf connect a room and money with creative freedom?|Material independence and private space can reduce constraints on women's intellectual work; creativity has social conditions as well as imaginative ones.
feminist|Woman as Other|Other (Beauvoir)|21,22|Beauvoir analyses woman as positioned as Other relative to man as normative Subject.|Gendered roles are socially produced rather than simply expressions of biological destiny.|A narrative defines a woman only as a hero's wife while giving him independent ambitions.|Otherness is a relation of power, not simply individual difference.|How could a novel's character descriptions reproduce woman as Other?|Men may appear as autonomous subjects while women are described only through their relationships, usefulness or difference from male norms.
feminist|Images of Women criticism|Images of Women criticism (Millett)|22|Images of Women criticism examines gendered representations and patriarchal assumptions in literature.|Millett's work connects literary sexual relations with power, questioning stereotypes and objectification.|Examine whether female characters are allowed agency or exist mainly as rewards for male heroes.|A female author does not automatically produce a non-patriarchal representation.|What evidence would support a critique of a stereotyped female character?|Show how narration, actions, dialogue and plot limit her agency or repeat gendered assumptions; support the claim with textual patterns.
feminist|Gynocriticism|Gynocriticism (Showalter)|22,23|Gynocriticism studies women as writers and their literary histories, forms and traditions.|Showalter shifts attention from criticism of male representations to women's literary production and its conditions.|Trace recurring themes and publishing barriers across women novelists.|It differs in focus from reading men's texts for images of women.|How does gynocriticism differ from Images of Women criticism?|Gynocriticism centres women's writing and traditions; Images of Women criticism focuses on gendered representations, often in male-authored texts.
feminist|Ecriture feminine|Ecriture feminine (Cixous)|23,24|Cixous's ecriture feminine imagines writing that disrupts patriarchal exclusions and fixed hierarchies.|Bodily experience, multiplicity and openness inform the proposal. It should not be reduced to a rule that all women naturally write alike.|A text challenges rigid narrative closure and gender binaries through multiple voices.|Feminine writing is a theoretical possibility, not a guaranteed property of every female author's text.|Why is equating ecriture feminine with all writing by women misleading?|The concept concerns a disruptive mode of writing and its relation to power and embodiment. Authorial sex alone does not establish that textual mode.
feminist|Black feminist criticism|Black feminist criticism (Smith)|24|Black feminist criticism examines interconnected racial, gendered and classed structures in Black women's lives and writing.|Barbara Smith calls attention to Black women's cultural specificity and exclusion from dominant critical traditions.|Analyse how a Black female character's options are shaped jointly by race, class and gender.|There is no single uniform experience shared by all Black women.|Why might a gender-only reading miss an important feature of a Black woman's narrative?|Gendered experience is shaped by racial and class relations; treating these as separate or ignoring them can erase the narrative's particular structures of power.
feminist|Postcolonial feminism|Postcolonial feminism (Spivak)|25|Postcolonial feminism examines gender through colonial histories and unequal global relations.|Spivak and Mohanty challenge claims to represent all women through a universal Western model, asking who speaks and who is heard.|Question a report that portrays all non-Western women as equally passive.|Challenging universalism does not require abandoning criticism of gender oppression.|Why is the phrase 'the typical Third World woman' problematic?|It can homogenise different histories, classes and forms of agency, reproducing the very representational hierarchy that feminist analysis should investigate.
psycho|The unconscious|The unconscious|26|In psychoanalytic theory, unconscious processes shape thoughts and actions beyond awareness.|Freud's interpretive framework connects repression, conflict, dreams and symptoms. It is a theoretical lens, not automatic proof of a character's diagnosis.|A recurring unexplained fear is read alongside a narrative's suppressed conflict.|A literary psychoanalytic interpretation is not a clinical diagnosis of the author.|Why should a critic avoid diagnosing an author solely from a fictional character?|Fiction is mediated and invented; a textual pattern cannot by itself establish the author's mental condition. Present the claim as an interpretation with evidence and limits.
psycho|Oedipus complex|Oedipus complex|26,27|The Oedipus complex is Freud's theory of childhood desire, rivalry and identification within family relations.|It has influenced interpretations of family conflict and Hamlet, but its universality and assumptions are contested.|Read a character's parental rivalry through an Oedipal lens and test the reading against the text.|A contested psychoanalytic theory is not an established universal developmental law.|Does a son's closeness to his mother prove an Oedipus complex?|No. Such closeness permits many explanations; an Oedipal interpretation needs careful textual support and acknowledgement of its theoretical assumptions.
psycho|Drives and defenses|Drives and defenses|27,28|Drives are motivating pressures; defenses manage anxiety and threatening psychic conflict in psychoanalytic theory.|Repression excludes material from awareness; projection attributes unwanted feelings to others; sublimation redirects impulses into socially valued forms.|A jealous character repeatedly accuses others of jealousy, suggesting projection as one reading.|A defense is not necessarily a consciously planned lie.|How do repression and projection differ?|Repression keeps threatening material out of awareness; projection locates an unwanted feeling or impulse in someone else.
psycho|Dream-work|Dream-work|28|Freudian dream-work transforms latent material into the dream's manifest form.|Condensation brings several associations into one image; displacement shifts emphasis to an associated substitute.|One dream figure combines traits of several important people.|Manifest content is the remembered dream; latent content is the inferred material transformed by dream-work.|How can one dream figure representing several people illustrate condensation?|Several associations converge in a single image. Displacement would instead shift emphasis from one significant object or thought to another associated one.
psycho|Object relations theory|Object relations theory|28|Object relations theory examines how early relationships and their internal representations shape the self.|Here an object is typically a person or part of a relationship as psychically represented, rather than a household item.|Analyse a narrative's recurring attachment and separation patterns.|It is not simply a theory about relations between physical objects.|Why might object relations theory help read a story about repeated abandonment?|It directs attention to how internalised early relationships organise expectations, attachment and responses to loss within the narrative.
psycho|Imaginary, Symbolic and Real|Imaginary, Symbolic and Real|29|Lacan's three orders are the Imaginary, Symbolic and Real.|The Imaginary concerns identification and images; the Symbolic concerns language, law and social relations; the Real names what resists symbolisation.|A character's ideal self-image is challenged by their position in social language and rules.|The Real is not everyday reality, and the three orders are not merely three successive life stages.|How does Lacan's Real differ from ordinary reality?|Reality is experienced and organised through meanings and representations; the Real designates what resists full symbolisation within that organisation.
psycho|Trauma|Trauma|29,30|Trauma theory considers overwhelming experience and difficulties of processing and representing it.|Literary readings may examine repetition, silence or disrupted chronology as ways a text engages traumatic experience.|A war narrative repeatedly returns to a scene without resolving it.|Fragmented narration alone does not prove trauma; formal patterns need contextual interpretation.|Can every gap in a narrative be treated as a symptom of trauma?|No. Gaps serve many formal and rhetorical functions. A trauma reading must connect form with the work's represented experiences and other evidence.
poststructural|Logocentrism|Logocentrism|31|Logocentrism privileges an ultimate foundation that supposedly guarantees meaning.|Derrida questions claims to pure presence and the hierarchy of speech over writing, showing dependence on difference and mediation.|A claim that only spoken words convey an author's meaning privileges presence.|Questioning foundations does not mean ordinary communication never works.|Why does Derrida question the supposed purity of speech?|Speech also relies on repeatable signs, differences and conventions; the speaker's presence does not make meaning completely self-contained or fully controllable.
poststructural|Differance and aporia|Differance and aporia (Derrida)|31,32|Differance joins difference and deferral; aporia names a difficult interpretive impasse.|Meaning depends on relations to other signs and cannot become completely self-sufficient. Deconstruction attends to tensions that unsettle a text's apparent assurances.|A declaration of complete independence relies on terms and relations it rejects.|Differance is not merely procrastination, and every hesitation is not an aporia.|Why is a character delaying a decision not by itself an example of differance?|Differance concerns how signification works through differences and deferral. Personal delay may illustrate a parallel but cannot substitute for an analysis of language and textual relations.
poststructural|Jouissance|Jouissance (Kristeva)|32,33|Jouissance names an intense enjoyment that unsettles ordinary satisfaction and stable subjectivity.|Kristeva connects disruptive bodily and rhythmic dimensions of signification with challenges to orderly symbolic structures.|A text's rhythm and excess disturb a reader's secure interpretive position.|The term is theory-dependent and is not simply a synonym for happiness.|How might a text offer jouissance rather than comfortable pleasure?|It may unsettle stable meaning, identity and familiar reading expectations through disruptive rhythm, multiplicity or excess.
poststructural|Death of the author|Death of the author (Barthes)|33|Barthes challenges the author's intention as the final authority over a text's meaning.|A text draws on multiple cultural voices; interpretation attends to their relations and the reader's encounter rather than seeking one biographical key.|A writer's explanation does not exhaust the meanings readers can support from a text.|It does not mean the author literally dies or evidence becomes irrelevant.|Does the death of the author mean an unsupported reading is as good as any other?|No. It challenges one source of final authority. Interpretations still need reasoned engagement with language, conventions and textual evidence.
poststructural|Rhizome|Rhizome|33,34|A rhizome models thought as multiple connections without one organising root.|Deleuze and Guattari contrast it with hierarchical tree models. Connections can grow through diverse entry points rather than one required sequence.|Map a cultural movement through intersecting music, migration, technology and politics.|A rhizome is a conceptual model, not a claim that organisations have no power relations.|How would a rhizomatic reading differ from tracing one original source?|It follows multiple intersecting connections and transformations instead of making every element descend from a single privileged origin.
poststructural|Deterritorialization and becoming|Deterritorialization;Becoming|34|Deterritorialization loosens established arrangements; becoming concerns transformation beyond fixed identities.|These processes can be followed by reterritorialization, where new structures stabilise relations. Change is not automatically emancipatory.|A migrant cultural form disrupts an inherited category and is later marketed under a new label.|Becoming is not simply adopting another fixed identity as a final destination.|Can a disrupted cultural form become newly fixed or commercialised?|Yes. Deterritorializing changes can be followed by reterritorialization, as institutions or markets stabilise and contain the transformed practice.
poststructural|Disciplinary discourse|Disciplinary discourse (Foucault)|34,35|Disciplinary discourse links knowledge, norms and institutional practices that shape subjects.|Surveillance, examinations and normalisation can make people regulate themselves. Power is productive as well as restrictive.|A school ranking system shapes what pupils understand as normal ability and achievement.|Foucauldian power is not limited to orders from one ruler.|How can an examination exercise disciplinary power beyond assigning marks?|It classifies and compares students, establishes norms and encourages self-monitoring, connecting knowledge of individuals with institutional control.
postmodern|Capitalism and postmodern culture|Capitalism (Eagleton)|36|Eagleton links postmodern culture to conditions and contradictions of capitalism.|His Marxist critique questions whether fragmentation and anti-totalising attitudes weaken collective criticism of exploitation.|A cultural celebration of endless consumer choice coexists with concentrated economic power.|This is a critical argument about postmodernism, not a definition accepted by every theorist.|Why might Eagleton question the political value of celebrating fragmentation?|It can make collective accounts of exploitation and coordinated political opposition harder to sustain, while leaving capitalist organisation insufficiently challenged.
postmodern|Grand narratives|Grand narrative (Lyotard)|36,37|Grand narratives are overarching accounts that legitimise knowledge or historical development.|Lyotard characterises postmodernity through suspicion of such totalising accounts and attention to local narratives and heterogeneous language games.|A claim that one model explains all human progress is a grand narrative.|A grand narrative is not just a long novel.|What makes an account of inevitable universal progress a grand narrative?|It offers a sweeping legitimating story that incorporates diverse histories into one supposedly universal developmental path.
postmodern|Intertextuality|Intertextuality (Kristeva)|37|Intertextuality concerns how texts absorb, transform and relate to other texts and discourses.|Kristeva's concept challenges the idea of a wholly self-contained original work. Relations can be explicit or implicit.|A modern advertisement adapts the wording of a familiar proverb.|Intertextuality is broader than direct quotation and is not identical with plagiarism.|Can a text be intertextual without naming another work?|Yes. Genre conventions, transformed phrases, allusions and shared discourses can connect texts without an explicit citation in the work itself.
postmodern|Hyperreality|Hyperreality (Baudrillard)|37,38|Hyperreality describes a condition in which simulation unsettles the distinction between representation and the real.|Baudrillard analyses signs and models that shape what counts as reality rather than simply copying a prior original.|A curated tourist experience becomes the standard by which an actual place is judged.|An inaccurate photograph alone does not establish hyperreality.|How can a staged tourist village illustrate hyperreality?|Its designed image may become the accepted model of authenticity, so visitors judge lived places against the simulation rather than the reverse.
postmodern|Pastiche|Pastiche (Jameson)|38|Jameson's pastiche imitates styles without parody's clear satirical edge.|He connects stylistic recycling with postmodern culture and weakened historical depth. Other critics dispute the scope of this diagnosis.|A film assembles recognisable past styles without critically targeting them.|Pastiche is not the same as parody, though a work can mix modes.|What distinction would Jameson draw between pastiche and parody?|Both imitate styles, but parody involves critical or satirical distance, while pastiche is comparatively neutral imitation in his account.
postcolonial|Othering|Othering|39|Othering constructs a group as alien or inferior against a dominant group's norm.|Representation can secure an unequal identity relation by repeating stereotypes and denying internal diversity.|A report depicts a community only as irrational while treating its observers as naturally rational.|Difference alone is not othering; hierarchy and representational power matter.|How can a seemingly sympathetic account still other a community?|It may portray people as uniformly helpless and deny their agency, positioning the observer as the only capable interpreter or rescuer.
postcolonial|Diaspora|Diaspora|39,40|Diaspora refers to dispersed communities and their continuing relations with a homeland and other locations.|Diasporic identities can involve memory, belonging and change across places. Dispersal does not produce one uniform experience.|A community maintains language and family connections across several countries.|Diaspora and every individual act of travel are not interchangeable.|Why can diasporic identity involve both continuity and change?|People sustain memories and affiliations while forming new practices and relationships in their places of settlement.
postcolonial|Hybridity|Hybridity|40|Hybridity concerns cultural meaning and identity produced through encounters that unsettle pure categories.|Bhabha's third space stresses negotiation and transformation, not simply adding two untouched cultures together.|A cultural performance reworks several traditions into meanings that fit neither inherited category neatly.|Hybridity is not proof that colonial power relations have disappeared.|Why is describing hybridity as a harmonious fifty-fifty mixture inadequate?|It overlooks unequal power, conflict and negotiation, and assumes the original cultures were pure and stable units.
postcolonial|Double consciousness|Double consciousness|40,41|Du Bois's double consciousness describes a divided self-awareness under racial domination.|A person experiences selfhood while also confronting the devaluing gaze of a dominant society. The concept has a specific African American intellectual history.|A marginalised speaker anticipates how a dominant audience will judge their identity.|It is not merely being bilingual or having two hobbies.|How does double consciousness exceed simple awareness of two cultures?|It involves a power-laden tension between self-understanding and an imposed devaluing perspective, not just knowledge of multiple cultural practices.
postcolonial|Subaltern|Subaltern|41,25|The subaltern names people structurally excluded from dominant channels of power and representation.|Spivak questions whether dominant frameworks can recognise subaltern speech without overwriting it. The issue is audibility and representation, not literal inability to produce words.|An institution claims to speak for a marginalised group while filtering out its own accounts.|Subaltern is not a casual synonym for anyone who feels disadvantaged.|What does 'the subaltern cannot speak' ask us to examine?|How institutions and dominant knowledge systems prevent marginalised people's speech from being recognised on its own terms, including when intellectuals claim to represent them.
postcolonial|Mimicry|Mimicry|41|Bhabha's mimicry concerns colonial imitation that remains marked as different.|The demand for similarity and continued exclusion creates ambivalence and can unsettle colonial authority, although resistance is not guaranteed.|Colonial education invites imitation of the ruler's manners while withholding equal status.|Mimicry is not always a consciously planned parody.|Why can colonial mimicry threaten as well as support authority?|It reproduces dominant forms but reveals that those forms are repeatable and imperfectly controlled; the desired resemblance also exposes the instability of colonial difference.
postcolonial|Neocolonialism|Neocolonialism|42|Neocolonialism describes indirect forms of domination after formal colonial rule.|Economic, political and cultural dependencies can preserve unequal power without direct colonial administration.|A formally independent country's choices are constrained by unequal financial and cultural relations.|Political independence does not by itself establish equal power, but every foreign exchange is not domination.|What evidence would strengthen a claim of neocolonial dependence?|Show sustained asymmetrical control over resources, decisions or representation, rather than relying solely on the presence of imported goods or foreign language use.
culture|Culture|Culture|43|Culture includes systems of meaning, creative practices and ways of life.|Williams broadens attention beyond elite artistic achievements to ordinary lived practices, while definitions remain contested.|Study food rituals or television viewing as meaningful cultural practices.|A broad definition does not imply that every practice has identical value or power.|Why would Williams treat an everyday festival as culture?|It expresses shared practices and meanings within a way of life, so culture extends beyond a canon of prestigious artworks.
culture|Popular culture|Popular culture|43,44|Popular culture concerns widely circulating or everyday cultural practices and products.|The term can refer to mass consumption, culture made by people, or what is excluded from high-cultural canons. Audiences can actively interpret its meanings.|Fans use a television character to express identities different from a producer's preferred message.|Popularity does not automatically mean passive acceptance of a single message.|Can audiences resist meanings in a popular television programme?|Yes. They may reinterpret, selectively use or contest its messages, though their possibilities remain shaped by textual and social conditions.
culture|Consumption|Consumption|44|Cultural consumption involves using and interpreting products as meaningful practices.|Choices of clothing, media or commodities can communicate identity and status. Analysis connects audience agency with markets and social conditions.|A music preference signals belonging to a peer group.|Consumption is not merely purchasing, and consumers are not necessarily passive.|How can wearing a brand communicate more than practical use?|Its culturally coded associations can signal status, identity or group membership, depending on the audience and context.
culture|Representation|Representation (Hall)|44,45,46|Hall treats representation as meaning production through concepts and signs.|His constructionist approach emphasises shared codes and social practices rather than a simple mirror of things or private intention.|Traffic-light colours acquire their significance through an established code.|Meaning construction does not mean the material world does not exist.|How does Hall's constructionism differ from a purely intentional account of meaning?|An individual cannot make signs mean anything at will; communication depends on socially available conceptual and signifying systems, which can also be contested.
'''
